// V2: business_sector is now OPTIONAL. The agent infers it from the site.
// Required: business_name + business_url only.
const input = $input.first().json.body || $input.first().json;

const headers = $input.first().json.headers || {};
if (headers['x-webhook-secret'] !== $vars.WEBHOOK_SECRET) {
  throw new Error('Unauthorized — bad webhook secret');
}

const required = ['business_name', 'business_url'];
const missing = required.filter(k => !input[k]);
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);

return [{
  json: {
    business_name: String(input.business_name).trim(),
    business_url: String(input.business_url).trim(),
    business_sector: input.business_sector ? String(input.business_sector).trim().toLowerCase() : null,
    instagram_handle: input.instagram_handle || null,
    contact_email: input.contact_email || null,
    contact_name: input.contact_name || null,
    source: input.source || 'manual'
  }
}];

const rows = $input.first().json;
const row = Array.isArray(rows) ? rows[0] : rows;
if (!row || !row.id) throw new Error('Failed to upsert lead');

return [{
  json: {
    lead_id: row.id,
    business_name: row.business_name,
    business_url: row.business_url
  }
}];

// Strip scripts, styles, comments, tags. Truncate.
const lead = $('Extract lead_id').first().json;
const out = $input.first().json;
let rawHtml = '';
if (typeof out === 'string') rawHtml = out;
else if (out && out.data) rawHtml = String(out.data);
else if (out && out.body) rawHtml = String(out.body);

const scrape_failed = !rawHtml || rawHtml.length < 200;
let cleaned;
if (scrape_failed) {
  cleaned = `[NO_CONTENT_AVAILABLE]\nBusiness: ${lead.business_name}\nURL: ${lead.business_url}`;
} else {
  cleaned = rawHtml
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 8000);
}

return [{
  json: {
    lead_id: lead.lead_id,
    business_name: lead.business_name,
    business_url: lead.business_url,
    scrape_failed,
    raw_html_snippet: cleaned.slice(0, 2000),
    cleaned_content: cleaned
  }
}];

// Parse Step 1 response. Carry forward the lead context.
const response = $input.first().json;
const ctx = $('Clean & truncate HTML').first().json;

let text;
try { text = response.content[0].text; }
catch (e) { throw new Error('Claude response missing content[0].text: ' + JSON.stringify(response).slice(0, 400)); }

text = text.trim().replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '');

let parsed;
try { parsed = JSON.parse(text); }
catch (e) { throw new Error('Step 1 returned non-JSON: ' + text.slice(0, 400)); }

// Required fields. Throw if missing — caught by n8n error handler.
for (const k of ['inferred_sector', 'what_they_sell', 'understanding_confidence']) {
  if (!(k in parsed)) throw new Error(`Step 1 missing field: ${k}`);
}

const usage = response.usage || {};
const tokens_in = usage.input_tokens || 0;
const tokens_out = usage.output_tokens || 0;
const cost_usd = (tokens_in / 1e6) * 3 + (tokens_out / 1e6) * 15;

return [{
  json: {
    lead_id: ctx.lead_id,
    business_name: ctx.business_name,
    business_url: ctx.business_url,
    raw_html_snippet: ctx.raw_html_snippet,
    scrape_failed: ctx.scrape_failed,
    understanding: parsed,
    step1_tokens_in: tokens_in,
    step1_tokens_out: tokens_out,
    step1_cost_usd: Number(cost_usd.toFixed(4))
  }
}];

const response = $input.first().json;
const ctx = $('Parse Step 1').first().json;

let text;
try { text = response.content[0].text; }
catch (e) { throw new Error('Claude response missing content[0].text'); }
text = text.trim().replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '');

let parsed;
try { parsed = JSON.parse(text); }
catch (e) { throw new Error('Step 2 returned non-JSON: ' + text.slice(0, 400)); }

for (const k of ['tasks', 'pitch_hook', 'total_hours_lost_weekly', 'total_cost_annual']) {
  if (!(k in parsed)) throw new Error(`Step 2 missing field: ${k}`);
}
if (!Array.isArray(parsed.tasks) || parsed.tasks.length < 3 || parsed.tasks.length > 5) {
  throw new Error(`Expected 3-5 tasks, got ${parsed.tasks?.length ?? 'none'}`);
}

const usage = response.usage || {};
const tokens_in = usage.input_tokens || 0;
const tokens_out = usage.output_tokens || 0;
const cost_usd = (tokens_in / 1e6) * 3 + (tokens_out / 1e6) * 15;

return [{
  json: {
    ...ctx,
    tasks_response: parsed,
    step2_tokens_in: tokens_in,
    step2_tokens_out: tokens_out,
    step2_cost_usd: Number(cost_usd.toFixed(4))
  }
}];

// Merge both Claude responses into the final diagnostic payload.
// Compute a single confidence score (geometric mean: penalises if either step is weak).
const ctx = $input.first().json;
const u = ctx.understanding;
const t = ctx.tasks_response;

const u_conf = Number(u.understanding_confidence ?? 0);
const a_conf = Number(t.automation_potential_score ?? 0);
// Weighted confidence: understanding matters more than automation potential.
const confidence = Math.round((u_conf * 0.7 + a_conf * 0.3) * 100) / 100;

const auto_continue = confidence >= 0.6 && !ctx.scrape_failed;
const lead_status_after = auto_continue ? 'diagnosed' : 'quarantine';

// Build a unified raw_response object that downstream consumers (Schema Builder,
// Pitcher) can read without knowing the V1 vs V2 split.
const raw_response = {
  schema_version: 'diagnoser-v2',
  business_name: ctx.business_name,
  inferred_sector: t.inferred_sector || u.inferred_sector,
  inferred_subsector: t.inferred_subsector || u.inferred_subsector,
  understanding: u,
  tasks: t.tasks,
  total_hours_lost_weekly: t.total_hours_lost_weekly,
  total_cost_annual: t.total_cost_annual,
  pitch_hook: t.pitch_hook,
  schema_accent_color: t.schema_accent_color || '#6366f1',
  automation_potential_score: a_conf,
  understanding_confidence: u_conf,
  confidence
};

const total_cost_usd = Number((ctx.step1_cost_usd + ctx.step2_cost_usd).toFixed(4));

return [{
  json: {
    lead_id: ctx.lead_id,
    business_name: ctx.business_name,
    raw_html_snippet: ctx.raw_html_snippet,
    scrape_failed: ctx.scrape_failed,
    raw_response,
    confidence,
    auto_continue,
    lead_status_after,
    inferred_sector_for_lead: raw_response.inferred_sector,
    // flat columns for Supabase insert
    inferred_sector: raw_response.inferred_sector,
    inferred_subsector: raw_response.inferred_subsector,
    what_they_sell: u.what_they_sell,
    target_customer: u.target_customer,
    how_they_sell: u.how_they_sell,
    contact_channels: u.contact_channels || [],
    team_size_estimate: u.team_size_estimate,
    price_range_visible: u.price_range_visible,
    key_services_or_offers: u.key_services_or_offers || [],
    website_quality_score: u.website_quality_score,
    understanding_confidence: u_conf,
    understanding_notes: u.understanding_notes,
    automation_potential_score: a_conf,
    schema_accent_color: raw_response.schema_accent_color,
    total_hours_lost_weekly: t.total_hours_lost_weekly,
    total_cost_annual: t.total_cost_annual,
    pitch_hook: t.pitch_hook,
    step1_tokens_in: ctx.step1_tokens_in,
    step1_tokens_out: ctx.step1_tokens_out,
    step2_tokens_in: ctx.step2_tokens_in,
    step2_tokens_out: ctx.step2_tokens_out,
    api_cost_usd: total_cost_usd
  }
}];

